#!/usr/bin/env python3
"""
Applies the real, evidence-based root-cause fix for the egress live-Docker
CI failure: Check()'s helper container (and this test file's own
independent verification helpers) was missing --cap-add NET_ADMIN. Listing
a netlink-backed ruleset (nft list, and iptables -S/-C once they resolve
through the nft-compat backend) requires that capability just as much as
inserting a rule does -- an unprivileged container gets "Operation not
permitted (you must be root)" on a pure read. This is confirmed directly
from the diagnostics added in the previous round (see the CI log you
pasted back), not another guess. The two earlier nft/legacy-backend fixes
were reasonable but were not what was actually failing.

Applied by content-anchor (same approach as the last round's
apply_egress_diagnostics.py), not a line-numbered patch, so it is immune to
line-number drift against your actual pushed branch. Safe to run twice --
it detects its own prior work per-replacement and skips it.

Run from the repo root (isthmus/):

    python3 apply_egress_netadmin_fix.py
"""
import json
import sys

REPLACEMENTS = json.loads('[\n  {\n    "file": "go-host/internal/egress/egress.go",\n    "old": "// non-capabilities convention for why doctor/security-check never mutate).\\nfunc Check(ctx context.Context, run Runner) Result {\\n",\n    "new": "// non-capabilities convention for why doctor/security-check never mutate).\\n//\\n// Check\'s helper container is granted --cap-add NET_ADMIN even though its\\n// script never inserts a rule — a real, live-CI-caught bug, not a guess:\\n// listing a netlink-backed ruleset (`nft list chain ...`, and `iptables -S`/\\n// `-C` once they resolve through the nft-compat backend, as they do on\\n// Debian/Ubuntu by default) opens a netlink socket, and the kernel requires\\n// CAP_NET_ADMIN to do that regardless of whether the caller intends to\\n// write anything — an unprivileged container gets \\"Operation not permitted\\n// (you must be root)\\" on a pure list/check just as it would on an insert.\\n// Two earlier fix attempts here targeted the nft-vs-legacy-iptables backend\\n// split (see detectAndScript\'s doc comment) because that\'s a real,\\n// documented class of bug in this exact \\"container manipulates the host\'s\\n// firewall\\" pattern — but a live CI run\'s own diagnostic dump (added to\\n// gather ground truth after both of those fixes failed to change the\\n// outcome) showed the actual failure directly: every read attempted by the\\n// unprivileged verification container failed with \\"Operation not permitted\\n// (you must be root)\\"/\\"netlink: Error: cache initialization failed:\\n// Operation not permitted\\", regardless of backend. The capability, not the\\n// backend, was the missing piece — granting it here does not weaken the\\n// \\"never mutates\\" guarantee below, since capability governs what the\\n// container is *allowed* to do, not what checkScript\'s own read-only\\n// commands *choose* to do (see TestScripts_DetectBothNftAndLegacyBackends\\n// and TestCheck_Linux_NeverMutates for the tests that keep that guarantee\\n// verified independently of this capability grant).\\nfunc Check(ctx context.Context, run Runner) Result {\\n",\n    "label": "egress.go#0"\n  },\n  {\n    "file": "go-host/internal/egress/egress.go",\n    "old": "\\t}\\n\\targs := []string{\\"run\\", \\"--rm\\", \\"--network\\", \\"host\\", helperImage, \\"sh\\", \\"-c\\", checkScript()}\\n\\tif _, err := run.Run(ctx, \\"docker\\", args...); err != nil {\\n",\n    "new": "\\t}\\n\\targs := []string{\\"run\\", \\"--rm\\", \\"--network\\", \\"host\\", \\"--cap-add\\", \\"NET_ADMIN\\", helperImage, \\"sh\\", \\"-c\\", checkScript()}\\n\\tif _, err := run.Run(ctx, \\"docker\\", args...); err != nil {\\n",\n    "label": "egress.go#1"\n  },\n  {\n    "file": "go-host/internal/egress/egress_test.go",\n    "old": "\\nfunc TestCheck_Linux_NeverMutates(t *testing.T) {\\n",\n    "new": "\\n// TestCheck_Linux_NeverMutates locks in the \\"never mutates\\" guarantee at\\n// the level that actually matters: the shell script Check\'s helper\\n// container runs contains no insert command under either backend. It\\n// deliberately does NOT assert anything about --cap-add NET_ADMIN being\\n// absent from the container\'s argv — a real live-CI run proved that\\n// capability grant is required for a pure read too (listing a\\n// netlink-backed ruleset needs CAP_NET_ADMIN regardless of intent to write;\\n// see Check\'s doc comment for the full story), so Check legitimately\\n// carries the same capability as Ensure. \\"Never mutates\\" is a property of\\n// what checkScript\'s commands *do*, not of what capabilities the container\\n// *has* — conflating the two is exactly what let a real bug (Check unable\\n// to read the ruleset at all) hide behind this test for two fix rounds.\\nfunc TestCheck_Linux_NeverMutates(t *testing.T) {\\n",\n    "label": "egress_test.go#0"\n  },\n  {\n    "file": "go-host/internal/egress/egress_test.go",\n    "old": "\\tjoined := strings.Join(run.calls[0].args, \\" \\")\\n\\tif strings.Contains(joined, \\"-I \\") || strings.Contains(joined, \\"--cap-add\\") || strings.Contains(joined, \\"nft insert\\") {\\n\\t\\tt.Fatalf(\\"Check: must never mutate (no -I insert, no nft insert, no NET_ADMIN) — got argv %q\\", joined)\\n\\t}\\n",\n    "new": "\\tjoined := strings.Join(run.calls[0].args, \\" \\")\\n\\tif strings.Contains(joined, \\"-I \\") || strings.Contains(joined, \\"nft insert\\") {\\n\\t\\tt.Fatalf(\\"Check: must never mutate (no -I insert, no nft insert) — got argv %q\\", joined)\\n\\t}\\n\\tif !strings.Contains(joined, \\"--cap-add\\") || !strings.Contains(joined, \\"NET_ADMIN\\") {\\n\\t\\tt.Fatalf(\\"Check: expected --cap-add NET_ADMIN — reading a netlink-backed ruleset requires it even for a pure list/check (see Check\'s doc comment) — got argv %q\\", joined)\\n\\t}\\n",\n    "label": "egress_test.go#1"\n  },\n  {\n    "file": "go-host/internal/egress/live_docker_test.go",\n    "old": "// detectAndScript itself — an earlier version of this helper checked only\\n// legacy `iptables -C`, which is exactly why the first real CI run against\\n// ubuntu-24.04 reported \\"not found\\" for a rule Ensure had, in fact, just\\n",\n    "new": "// detectAndScript itself — an earlier version of this helper checked only\\n// legacy `iptables -C`, which is exactly why an early real CI run against\\n// ubuntu-24.04 reported \\"not found\\" for a rule Ensure had, in fact, just\\n",\n    "label": "live_docker_test.go#0"\n  },\n  {\n    "file": "go-host/internal/egress/live_docker_test.go",\n    "old": "// would silently repeat that exact false negative on any nft-backed host.\\nfunc dockerUserRuleActive(t *testing.T) bool {\\n",\n    "new": "// would silently repeat that exact false negative on any nft-backed host.\\n//\\n// It also runs with --cap-add NET_ADMIN, confirmed necessary by real\\n// evidence, not assumption: without it, this container\'s own `nft list`/\\n// `iptables -S` calls failed with \\"Operation not permitted (you must be\\n// root)\\" — a pure read, no insert attempted — which is what made two\\n// earlier nft/legacy-backend fixes look like they weren\'t working: this\\n// helper\'s own check was the thing failing to read, not the underlying\\n// rule failing to exist. See egress.go\'s Check doc comment for the fuller\\n// explanation (Check itself had, and needed, the same fix).\\nfunc dockerUserRuleActive(t *testing.T) bool {\\n",\n    "label": "live_docker_test.go#1"\n  },\n  {\n    "file": "go-host/internal/egress/live_docker_test.go",\n    "old": "\\t// reaches this argv.\\n\\t_, err := exec.CommandContext(ctx, \\"docker\\", \\"run\\", \\"--rm\\", \\"--network\\", \\"host\\", helperImage, \\"sh\\", \\"-c\\", script).CombinedOutput() // nosemgrep: go.lang.security.audit.dangerous-exec-command.dangerous-exec-command\\n\\treturn err == nil\\n",\n    "new": "\\t// reaches this argv.\\n\\t_, err := exec.CommandContext(ctx, \\"docker\\", \\"run\\", \\"--rm\\", \\"--network\\", \\"host\\", \\"--cap-add\\", \\"NET_ADMIN\\", helperImage, \\"sh\\", \\"-c\\", script).CombinedOutput() // nosemgrep: go.lang.security.audit.dangerous-exec-command.dangerous-exec-command\\n\\treturn err == nil\\n",\n    "label": "live_docker_test.go#2"\n  },\n  {\n    "file": "go-host/internal/egress/live_docker_test.go",\n    "old": "//\\n// Why this exists: two prior fix attempts for this test\'s failure were\\n// each based on a plausible, externally-documented theory (first: Alpine\'s\\n// legacy iptables vs Ubuntu\'s nft-compat default; then: detecting and\\n// following whichever backend owns DOCKER-USER) and neither actually\\n// resolved the failure on the real CI runner. Two theory-based fixes\\n// failing in a row means the theory is missing something specific to this\\n// environment — the responsible next step is ground truth from the actual\\n// failing environment, not a third guess. This dumps exactly what\\n// iptables/nft resolve to and what they can see, from inside the same\\n// container context Ensure/Check use, so a real failure here carries the\\n// evidence needed to diagnose it instead of just the bare assertion.\\nfunc dumpContainerDiagnostics(t *testing.T) {\\n",\n    "new": "//\\n// Why this exists, and what it already found: two prior fix attempts for\\n// this test\'s failure were each based on a plausible, externally-documented\\n// theory (first: Alpine\'s legacy iptables vs Ubuntu\'s nft-compat default;\\n// then: detecting and following whichever backend owns DOCKER-USER) and\\n// neither actually resolved the failure on the real CI runner. This dump\\n// was added to get ground truth instead of a third guess — and on the very\\n// next CI run, it worked exactly as intended: every line came back\\n// \\"Operation not permitted (you must be root)\\" / \\"netlink: Error: cache\\n// initialization failed: Operation not permitted\\", on pure list/read\\n// commands, regardless of backend. That\'s what actually diagnosed the real\\n// bug (this container itself lacked --cap-add NET_ADMIN, now fixed — see\\n// egress.go\'s Check doc comment for the full explanation) rather than the\\n// two backend theories, which were reasonable but not what was actually\\n// failing. Left in place (not reverted) as ongoing tooling: any future\\n// live-Docker failure here gets a container-level ground-truth dump for\\n// free, without needing another diagnostics round-trip first.\\nfunc dumpContainerDiagnostics(t *testing.T) {\\n",\n    "label": "live_docker_test.go#3"\n  },\n  {\n    "file": "go-host/internal/egress/live_docker_test.go",\n    "old": "\\t// reaches this argv.\\n\\tout, err := exec.CommandContext(ctx, \\"docker\\", \\"run\\", \\"--rm\\", \\"--network\\", \\"host\\", helperImage, \\"sh\\", \\"-c\\", script).CombinedOutput() // nosemgrep: go.lang.security.audit.dangerous-exec-command.dangerous-exec-command\\n\\tif err != nil {\\n",\n    "new": "\\t// reaches this argv.\\n\\tout, err := exec.CommandContext(ctx, \\"docker\\", \\"run\\", \\"--rm\\", \\"--network\\", \\"host\\", \\"--cap-add\\", \\"NET_ADMIN\\", helperImage, \\"sh\\", \\"-c\\", script).CombinedOutput() // nosemgrep: go.lang.security.audit.dangerous-exec-command.dangerous-exec-command\\n\\tif err != nil {\\n",\n    "label": "live_docker_test.go#4"\n  },\n  {\n    "file": "docs/ADR-013-p8-05-egress-network-controls.md",\n    "old": "\\n**Scope: Linux only, disclosed gap on macOS.** The mechanism above depends on the helper container sharing the host\'s real network namespace (`--network host`) so the `iptables` rule it inserts lands in the *host\'s* `DOCKER-USER` chain, not a namespace-local one. On native Linux that is exactly what `--network host` does. On Docker Desktop for Mac, it is not: per [Docker\'s own community forum](https://forums.docker.com/t/mac-host-network-driver-beta-feature/141989), the beta `--network host` support there is implemented via \\"proxies/forwarding rules,\\" not real namespace sharing — so the same helper-container invocation would silently insert a rule nowhere that matters, producing a false sense of security rather than a real block. Rather than ship a mechanism that looks identical but only works on one platform, `internal/egress.Ensure`/`Check` no-op/report a disclosed `LevelWarn` gap (never a false `LevelPass`) on any non-Linux `GOOS`, named explicitly in both the CLI warning text and the `doctor` output. This mirrors this project\'s existing precedent for native Windows never being a supported host (POSIX-only mount paths, see `.github/workflows/ci.yml`\'s `go-host-os-matrix` job comment) — a limitation stated plainly rather than implied away, with a path to close it (native Linux hosts, or a Linux VM/WSL2, get the real protection today; a Windows-container or Mac-native mechanism is future work, not silently assumed).\\n",\n    "new": "\\n**The actual root cause of the live-Docker CI failure — confirmed by evidence, not a third theory.** The backend-detection fix above did not, in fact, resolve the CI failure: the exact same test failed again afterward, identically. Rather than guess a third externally-plausible theory, a diagnostic-only CI step and a container-level diagnostic dump (`dumpContainerDiagnostics` in `internal/egress/live_docker_test.go`) were added to capture real evidence from the failing environment on the next run. That evidence was unambiguous: every read command the verification container attempted — `nft list chain`, `iptables -S`, `nft list ruleset` — failed with `Operation not permitted (you must be root)` / `netlink: Error: cache initialization failed: Operation not permitted`, on pure list/read commands, no insert attempted, regardless of backend. The real bug had nothing to do with nft vs. legacy iptables: `Check()`\'s helper container (and this test file\'s own independent `dockerUserRuleActive`/`dumpContainerDiagnostics` verification helpers) were never granted `--cap-add NET_ADMIN`. Listing a netlink-backed ruleset opens a netlink socket, and the kernel requires `CAP_NET_ADMIN` for that regardless of whether the caller intends to write anything — an unprivileged container is refused on a pure read exactly as it would be on an insert. `Ensure()`\'s helper container already had the capability (needed for its insert), which is why installing the rule worked all along; only the independent verification path — both this package\'s own `Check()` and this test\'s separate verification helpers — could never actually confirm it, on any host, since the day the mechanism first ran against a real Docker daemon. The fix: grant `--cap-add NET_ADMIN` to `Check()`\'s helper container too (and to the test file\'s own independent verification helpers, so they don\'t share the bug they\'re meant to catch) — see `egress.go`\'s `Check` doc comment for the full explanation, and `TestCheck_Linux_NeverMutates`\'s updated doc comment for why granting the capability doesn\'t weaken the \\"never mutates\\" guarantee (that guarantee is about what `checkScript`\'s commands do, not what the container is permitted to do). The two nft/legacy-backend fixes above remain in place — that class of bug is real and documented elsewhere — but they were not, in the end, what this job\'s failure actually was.\\n\\n**Scope: Linux only, disclosed gap on macOS.** The mechanism above depends on the helper container sharing the host\'s real network namespace (`--network host`) so the `iptables` rule it inserts lands in the *host\'s* `DOCKER-USER` chain, not a namespace-local one. On native Linux that is exactly what `--network host` does. On Docker Desktop for Mac, it is not: per [Docker\'s own community forum](https://forums.docker.com/t/mac-host-network-driver-beta-feature/141989), the beta `--network host` support there is implemented via \\"proxies/forwarding rules,\\" not real namespace sharing — so the same helper-container invocation would silently insert a rule nowhere that matters, producing a false sense of security rather than a real block. Rather than ship a mechanism that looks identical but only works on one platform, `internal/egress.Ensure`/`Check` no-op/report a disclosed `LevelWarn` gap (never a false `LevelPass`) on any non-Linux `GOOS`, named explicitly in both the CLI warning text and the `doctor` output. This mirrors this project\'s existing precedent for native Windows never being a supported host (POSIX-only mount paths, see `.github/workflows/ci.yml`\'s `go-host-os-matrix` job comment) — a limitation stated plainly rather than implied away, with a path to close it (native Linux hosts, or a Linux VM/WSL2, get the real protection today; a Windows-container or Mac-native mechanism is future work, not silently assumed).\\n",\n    "label": "ADR-013.md#0"\n  }\n]')


def apply_one(r):
    path = r["file"]
    old = r["old"]
    new = r["new"]
    label = r["label"]
    try:
        with open(path, encoding="utf-8") as f:
            text = f.read()
    except FileNotFoundError:
        sys.exit(f"[FAIL] {label}: {path} not found. Nothing further was changed. "
                  f"Make sure you're running this from the repo root.")

    if new in text:
        print(f"[skip] {label}: already applied")
        return
    if old not in text:
        sys.exit(f"[FAIL] {label}: expected anchor text not found in {path}. "
                  f"Nothing in this file was changed by this run. Paste this "
                  f"message back (with the label) so the fix can be adjusted.")
    text = text.replace(old, new, 1)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    print(f"[ok]   {label}: applied to {path}")


if __name__ == "__main__":
    for r in REPLACEMENTS:
        apply_one(r)
    print("Done. Now run: git diff --stat")
